package top.pxczxn.community.analytics.persistence; import com.baomidou.mybatisplus.core.mapper.BaseMapper; import org.apache.ibatis.annotations.*; import top.pxczxn.community.analytics.model.CreatorAnalyticsEvent; import java.time.LocalDateTime; import java.util.*;
@Mapper public interface CreatorAnalyticsEventMapper extends BaseMapper<CreatorAnalyticsEvent> { @Select("SELECT DATE(occurred_at) day, COUNT(*) count FROM creator_analytics_event WHERE author_user_id=#{userId} AND occurred_at>=#{from} GROUP BY DATE(occurred_at) ORDER BY day") List<Map<String,Object>> daily(@Param("userId")Long userId,@Param("from")LocalDateTime from); @Select("SELECT source_type source, COUNT(*) count FROM creator_analytics_event WHERE author_user_id=#{userId} AND occurred_at>=#{from} GROUP BY source_type ORDER BY count DESC") List<Map<String,Object>> sources(@Param("userId")Long userId,@Param("from")LocalDateTime from); @Select("SELECT search_term term, COUNT(*) count FROM creator_analytics_event WHERE author_user_id=#{userId} AND event_type='SEARCH_CLICK' AND search_term IS NOT NULL AND occurred_at>=#{from} GROUP BY search_term ORDER BY count DESC, term ASC LIMIT 20") List<Map<String,Object>> terms(@Param("userId")Long userId,@Param("from")LocalDateTime from); }
